/**
 * Cloudflare Worker entry: the Next.js app (built by OpenNext) plus cron triggers.
 * Cron runs call our own /api/cron/<job> route so all job code lives in the Next app.
 */
// @ts-expect-error: generated by `opennextjs-cloudflare build`
import handler from "./.open-next/worker.js";

type Env = { CRON_SECRET?: string } & Record<string, unknown>;
type Ctx = { waitUntil(p: Promise<unknown>): void };

const JOBS: Record<string, string> = {
  "0 9 * * *": "nightly-sync",
  "0 10 1 * *": "monthly-heatmaps",
};

export default {
  fetch: handler.fetch,
  async scheduled(event: { cron: string }, env: Env, ctx: Ctx) {
    const job = JOBS[event.cron];
    if (!job) return;
    const req = new Request(`https://internal/api/cron/${job}`, {
      method: "POST",
      headers: { authorization: `Bearer ${env.CRON_SECRET ?? ""}` },
    });
    ctx.waitUntil(handler.fetch(req, env, ctx));
  },
};
